<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { futureCapabilities } from '@footlab/shared';
import { api, errorMessage } from '../services/api';
import { useClub } from '../stores/club';
import StateNotice from '../components/StateNotice.vue';
import StatChart from '../components/StatChart.vue';
const club = useClub(); const scope = ref('club'), players = ref<any[]>([]), seasons = ref<any[]>([]), seasonId = ref(''), position = ref(''), left = ref(''), right = ref(''), result = ref<any>(), error = ref(''), busy = ref(false), per = ref(false);
const params = computed(() => scope.value === 'club' ? club.params : {});
async function load() { busy.value = true; error.value = ''; result.value = undefined; try { const [p, s] = await Promise.all([api.get('/players', { params: { ...params.value, ...(position.value ? { position: position.value } : {}), ...(seasonId.value ? { seasonId: seasonId.value } : {}), limit: 100 } }), api.get('/competitions/seasons', { params: params.value })]); players.value = p.data.items; seasons.value = s.data; left.value = players.value[0]?.id ?? ''; right.value = players.value[1]?.id ?? ''; } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
async function compare() { busy.value = true; error.value = ''; try { result.value = (await api.get('/comparisons', { params: { ...params.value, left: left.value, right: right.value, ...(seasonId.value ? { seasonId: seasonId.value } : {}) } })).data; } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
onMounted(load); watch([scope, () => club.selectedId], () => { seasonId.value = ''; load(); }); watch([position, seasonId], load);
const fields = computed(() => [{ key: 'appearances', label: 'Partidos registrados' }, { key: 'minutes', label: 'Minutos registrados' }, { key: per.value ? 'goalsPer90' : 'goals', label: per.value ? 'Goles / 90' : 'Goles' }, { key: 'assists', label: 'Asistencias' }, { key: 'yellowCards', label: 'Tarjetas amarillas' }, { key: 'redCards', label: 'Tarjetas rojas' }]);
const series = computed(() => result.value ? ['left', 'right'].map(side => ({ name: result.value[side].player.name, data: [result.value[side][per.value ? 'goalsPer90' : 'goals'], result.value[side].yellowCards, result.value[side].redCards] })) : []);
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">FOOTLAB LAB</span><h1>El contexto <span class="accent">marca la diferencia.</span></h1><p>Compara futbolistas con las mismas reglas y la misma temporada.</p></div><span class="pill">PLAYER VS PLAYER</span></div><div class="panel"><div class="filter-bar"><select v-model="scope" aria-label="Fuente de jugadores"><option value="club">Mi club</option><option value="pro">Fútbol profesional</option></select><select v-model="seasonId" aria-label="Temporada"><option value="">Todas las temporadas</option><option v-for="s in seasons" :key="s.id" :value="s.id">{{ s.name }} · {{ s.competition.name }}</option></select><select v-model="position" aria-label="Posición"><option value="">Todas las posiciones</option><option v-for="p in ['GK', 'DF', 'MF', 'FW']" :key="p">{{ p }}</option></select></div><form class="comparison-picker" @submit.prevent="compare"><label>PRIMER JUGADOR<select v-model="left" required><option v-for="p in players" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><span class="versus">VS</span><label>SEGUNDO JUGADOR<select v-model="right" required><option v-for="p in players" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><button class="button primary" :disabled="busy || !left || !right || left === right">Comparar <i aria-hidden="true" class="pi pi-arrow-right" /></button></form></div><StateNotice :loading="busy" :error="error" :empty="!busy && !players.length && !error" @retry="load" /><template v-if="result && !busy && !error"><div class="section-heading section-gap"><h2>Frente a frente</h2><label class="toggle"><input v-model="per" type="checkbox"> Goles por 90 minutos</label></div><div class="comparison-head"><RouterLink :to="{ path: `/players/${left}`, query: params }">{{ result.left.player.name }}<small>{{ result.left.player.position }}</small></RouterLink><span>VS</span><RouterLink :to="{ path: `/players/${right}`, query: params }">{{ result.right.player.name }}<small>{{ result.right.player.position }}</small></RouterLink></div><div class="panel"><div v-for="f in fields" :key="f.key" class="comparison-row"><strong>{{ result.left[f.key] ?? '—' }}</strong><span>{{ f.label }}</span><strong>{{ result.right[f.key] ?? '—' }}</strong></div><p class="chart-footnote">— significa dato no disponible. Los totales usan solo participaciones y eventos registrados.</p></div><div class="dashboard-grid section-gap"><div class="panel"><h3>{{ per ? 'Goles / 90 y tarjetas totales' : 'Totales registrados' }}</h3><StatChart :labels="[per ? 'Goles / 90' : 'Goles', 'Amarillas', 'Rojas']" :series="series" /></div><div class="panel"><h3>Evolución de goles registrados</h3><StatChart v-if="result.left.evolution.length" type="line" :labels="result.left.evolution.map((e: any) => new Date(e.date).toLocaleDateString('es'))" :series="[{ name: result.left.player.name, data: result.left.evolution.map((e: any) => e.goals) }]" /><StateNotice v-else empty /></div></div></template><section class="panel roadmap section-gap"><span class="eyebrow">LO QUE VIENE</span><h3>El laboratorio seguirá creciendo.</h3><p class="muted">Estas capacidades están previstas y todavía no están disponibles.</p><div class="roadmap-chips"><span v-for="feature in futureCapabilities" :key="feature"><i aria-hidden="true" class="pi pi-lock" /> {{ feature }}</span></div></section></section></template>
